 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    touches_edge = True
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and not seen[nx][ny]:
                        seen[nx][ny] = True
                        q.append((nx, ny))
            if not touches_edge:
                rs = [x for x, _ in cells]
                cs = [y for _, y in cells]
                side = max(max(rs)-min(rs)+1, max(cs)-min(cs)+1)
                color = 24 // side
                for x, y in cells:
                    out[x][y] = color
    return out
